    if (!job || [
        "complete",
        "failed",
        "cancelled"
    ].includes(job.status)) return job || null;
    job.cancelled = true;
    updateLoraDownloadJob(job, {
        status: "cancelled",
        message: "LoRA download cancelled.",
        error: ""
    });
    const socket = job.socket;
    if (socket) {
        try {
            socket.send(JSON.stringify({
                signal: "cancel"
            }));
        } catch  {}
        try {
            socket.close();
        } catch  {}
    }
    return job;
