    const hasVisualData = input.enabled === true || cleanVisualWords(input.aliases).length > 0 || Boolean(asString(input.positivePrompt).trim()) || Boolean(asString(input.referenceImageId).trim()) || Object.keys(cleanLoreModelPrompts(input.modelPrompts)).length > 0;
    if (!hasVisualData) return null;
