        [
            "1:1",
            1
        ],
        [
            "2:3",
            2 / 3
        ],
        [
            "3:2",
            3 / 2
        ],
        [
            "4:5",
            4 / 5
        ],
        [
            "5:4",
            5 / 4
        ],
        [
            "9:16",
            9 / 16
        ],
        [
            "16:9",
            16 / 9
        ]
